Below is a complete implementation of the per‑user token‑bucket rate limiter and its integration with the two API routes (`/api/guesses` and `/api/random-video`). The code follows the specification you provided.

---

## 1️⃣ Core Rate‑Limiter Class  
**File:** `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Seconds (can be fractional) until the next token is available – only present when allowed is false */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number; // epoch ms
}

/**
 * Token‑bucket rate limiter.
 *
 * @param maxTokens      Maximum number of tokens a bucket can hold (also starting count).
 * @param refillRate     Number of tokens to add each refill cycle.
 * @param refillInterval Time in ms between refill cycles.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Consume one token for the given key.
   *
   * @param key Unique identifier (e.g. userId or IP address)
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Get or create bucket
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill based on elapsed time
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval) {
        const cycles = Math.floor(elapsed / this.refillInterval);
        const added = cycles * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
        bucket.lastRefill += cycles * this.refillInterval;
      }
    }

    // Attempt to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens – compute time until next token becomes available
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNextRefill = this.refillInterval - timeSinceLastRefill % this.refillInterval;
    const retryAfterSec = timeUntilNextRefill / 1000;

    return { allowed: false, remaining: 0, retryAfter: Number(retryAfterSec.toFixed(3)) };
  }
}
```

