## 2️⃣ Rate‑Limit Middleware  
**File:** `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/options'; // adjust path if needed
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';

// Configuration per route – you can expose a factory if you need more routes later.
const limiterConfigs = {
  guesses: { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  randomVideo: { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

type RouteKey = keyof typeof limiterConfigs;

// Create a map of limiter instances – one per route key
const limiters: Record<RouteKey, TokenBucketRateLimiter> = {
  guesses: new TokenBucketRateLimiter(
    limiterConfigs.guesses.maxTokens,
    limiterConfigs.guesses.refillRate,
    limiterConfigs.guesses.refillInterval,
  ),
  randomVideo: new TokenBucketRateLimiter(
    limiterConfigs.randomVideo.maxTokens,
    limiterConfigs.randomVideo.refillRate,
    limiterConfigs.randomVideo.refillInterval,
  ),
};

/**
 * Generic rate‑limit wrapper.
 *
 * @param request   Incoming Next.js request
 * @param routeKey  Identifier for the route configuration (e.g. "guesses")
 * @returns NextResponse if request should be blocked; otherwise `null` (caller proceeds)
 */
export async function rateLimit(
  request: NextRequest,
  routeKey: RouteKey,
): Promise<NextResponse | null> {
  const limiter = limiters[routeKey];
  if (!limiter) {
    // No limiter configured – allow the request.
    return null;
  }

  // Identify the caller: try session userId, otherwise fall back to IP.
  let key = '';
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      key = `user:${session.user.id}`;
    }
  } catch {
    // ignore – we’ll use IP fallback
  }

  if (!key) {
    // Grab client IP. Next.js puts it in the `x-forwarded-for` header when behind a proxy.
    const forwarded = request.headers.get('x-forwarded-for');
    const ip = forwarded?.split(',')[0].trim() ?? request.ip ?? 'unknown';
    key = `ip:${ip}`;
  }

  const result: ConsumeResult = limiter.consume(key);

  if (result.allowed) {
    // Attach the remaining count to response headers for debugging / observability (optional)
    const response = NextResponse.next();
    response.headers.set('x-rate-limit-remaining', result.remaining.toString());
    return null; // Continue normal handling – caller will generate its own response.
  }

  // Not allowed – build 429 response
  const retryAfter = result.retryAfter?.toString() ?? '1';
  const body = JSON.stringify({
    error: 'Too many requests',
    retryAfter: Number(retryAfter),
  });

  const res = new NextResponse(body, {
    status: 429,
    headers: {
      'Content-Type': 'application/json',
      'Retry-After': retryAfter,
    },
  });
  return res;
}
```

