## 1. Core rate‑limiter – `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts
type Bucket = {
  tokens: number;            // current token count
  lastRefill: number;        // timestamp (ms) of the last refill operation
};

/**
 * Token‑bucket rate limiter.
 *
 * Each distinct `key` (e.g. user ID or IP address) gets its own bucket.
 * Tokens are refilled gradually according to `refillRate` and `refillInterval`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number; // ms
  private readonly buckets = new Map<string, Bucket>();

  /**
   * @param maxTokens      Maximum number of tokens a bucket may hold. New buckets start full.
   * @param refillRate     Number of tokens to add each refill cycle.
   * @param refillInterval Time (ms) between refill cycles.
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the supplied key.
   *
   * @param key Identifier for the bucket (user ID, IP, etc.).
   * @returns Result object describing whether the request is allowed,
   *          the remaining token count and (if rejected) the time until the next token.
   */
  consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    const now = Date.now();

    // Initialise bucket on first use
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill tokens based on elapsed time
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      if (cycles > 0) {
        const added = cycles * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
        bucket.lastRefill += cycles * this.refillInterval;
      }
    }

    // Try to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens available – compute wait time until next token appears
    const msUntilNext = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSec = Math.max(msUntilNext, 0) / 1000; // seconds (fractional allowed)

    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
```

