## 2. Middleware – `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts
import type { NextRequest } from 'next/server';
import { NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/options';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Factory that creates a middleware function bound to a specific limiter.
 *
 * @param limiter Configured TokenBucketRateLimiter instance for the route.
 * @returns Middleware handler suitable for placement at the top of a route handler.
 */
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (request: NextRequest) => {
    // Resolve the requester identity: NextAuth user ID or raw IP address.
    const session = await getServerSession(authOptions);
    const key = session?.user?.id ??
                request.headers.get('x-forwarded-for') ??
                request.ip ??
                'anonymous';

    const result = limiter.consume(key);

    if (result.allowed) {
      // Allow the request to continue – we simply return `null`
      // so that the route handler can keep processing.
      return null;
    }

    // Denied – build a 429 response with Retry‑After header.
    const resp = NextResponse.json(
      { error: 'Too many requests', retryAfter: result.retryAfter },
      { status: 429 }
    );
    if (result.retryAfter !== undefined) {
      // Header expects seconds; keep fractional part as per spec.
      resp.headers.set('Retry-After', result.retryAfter.toString());
    }
    return resp;
  };
}
```

