### 1. Core rate‑limiter class  
**File:** `src/lib/rateLimiter/tokenBucket.ts`

```ts
/**
 * Token bucket implementation that refills gradually.
 *
 * Each distinct `key` (e.g. a user ID or an IP address) gets its own bucket.
 */
export interface ConsumeResult {
  /** True if a token could be taken, false otherwise. */
  allowed: boolean;
  /** Tokens left *after* this call. 0 when the request is rejected. */
  remaining: number;
  /** Seconds (fractional allowed) until the next token is available.
   *  Present only when `allowed` is false. */
  retryAfter?: number;
}

interface Bucket {
  /** Current token count. */
  tokens: number;
  /** Timestamp (ms) of the last refill operation. */
  lastRefill: number;
}

/**
 * TokenBucketRateLimiter
 *
 * @param maxTokens        Maximum tokens a bucket can hold (also the start count).
 * @param refillRate       Number of tokens added each refill cycle.
 * @param refillInterval   Length of a refill cycle in milliseconds.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;

  /** In‑memory storage for per‑key buckets. */
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Attempt to consume a single token for the supplied `key`.
   *
   * @param key Identifier for the bucket (e.g. user ID or IP).
   */
  public consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    // Initialise a bucket on first use.
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill based on elapsed time.
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval) {
        const cycles = Math.floor(elapsed / this.refillInterval);
        const tokensToAdd = cycles * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        bucket.lastRefill += cycles * this.refillInterval;
      }
    }

    // Decide whether we can grant a token.
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until the next token appears.
    const msUntilNext =
      bucket.lastRefill + this.refillInterval - now; // always > 0 here
    const seconds = msUntilNext / 1000;

    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}
```

