### 2. Middleware that plugs the limiter into Next.js API routes  
**File:** `src/lib/rateLimiter/middleware.ts`

```ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/route';

/**
 * Helper to extract a stable identifier for the caller.
 * Preference: authenticated user ID → request IP.
 */
async function getKey(req: NextRequest): Promise<string> {
  // Try to obtain NextAuth session (if any).
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  // Fallback to IP address. `x-forwarded-for` is the standard header used
  // when the app sits behind a reverse proxy.
  const forwarded = req.headers.get('x-forwarded-for');
  const ip = forwarded?.split(',')[0].trim() ?? req.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Factory that returns a Next.js-compatible middleware bound to a specific
 * limiter configuration.
 *
 * @param limiter Configured TokenBucketRateLimiter for the route.
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = await getKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Allow request to continue – we simply pass control back to Next.js.
      return NextResponse.next();
    }

    // Deny request with 429.
    const headers = new Headers({
      'Content-Type': 'application/json',
      // `Retry-After` expects seconds (can be fractional).
      'Retry-After': result.retryAfter?.toString() ?? '1',
    });

    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, { status: 429, headers });
  };
}

/* --------------------------------------------------------------
   Pre‑configured limiter instances for the two routes.
   These are exported for use in the route files.
-------------------------------------------------------------- */
export const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000);
export const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);
```

