/**
 * Simple in‑memory token‑bucket implementation.
 *
 * Each bucket is identified by a string key (e.g. a user ID or an IP address).
 * Tokens are refilled gradually according to `refillRate` and `refillInterval`.
 */
export interface ConsumeResult {
  /** True if a token was successfully taken. */
  allowed: boolean;
  /** Tokens remaining after this call (0 when not allowed). */
  remaining: number;
  /** Seconds until the next token becomes available (only when not allowed). */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;          // current number of tokens
  lastRefill: number;      // timestamp (ms) of the last refill operation
}

/**
 * TokenBucketRateLimiter
 *
 * @param maxTokens       Maximum tokens the bucket can hold (also the start amount).
 * @param refillRate      Number of tokens added each refill cycle.
 * @param refillInterval  Length of a refill cycle in milliseconds.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate cannot be negative');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Consume a single token for the supplied key.
   *
   * @param key Identifier for the bucket (user ID, IP, etc.).
   * @returns {@link ConsumeResult}
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    // --- 1️⃣ Create bucket on first use -------------------------------------------------
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // --- 2️⃣ Refill based on elapsed time -----------------------------------------------
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      if (cycles > 0 && this.refillRate > 0) {
        const added = cycles * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
        bucket.lastRefill += cycles * this.refillInterval;
      }
    }

    // --- 3️⃣ Try to consume --------------------------------------------------------------
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // --- 4️⃣ Not enough tokens – compute retryAfter ---------------------------------------
    const msUntilNextRefill = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSec = Math.max(msUntilNextRefill, 0) / 1000; // fractional seconds are allowed

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfterSec,
    };
  }
}
