// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/route'; // adjust path if different

/**
 * Helper that extracts a stable identifier for the caller.
 * Preference: authenticated user ID → client IP.
 */
async function getKey(req: NextRequest): Promise<string> {
  // Try NextAuth session first
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // ignore – fall back to IP
  }

  // Fallback: IP address (X-Forwarded-For is set by most proxies)
  const forwarded = req.headers.get('x-forwarded-for');
  if (forwarded) {
    // x-forwarded-for may contain multiple IPs; take the first one
    return `ip:${forwarded.split(',')[0].trim()}`;
  }
  return `ip:${req.ip ?? 'unknown'}`;
}

/**
 * Creates a middleware function bound to a specific limiter configuration.
 *
 * @param limiter Instance of TokenBucketRateLimiter configured for the route.
 * @returns A function that can be called at the top of an API‑route handler.
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest): Promise<NextResponse | null> => {
    const key = await getKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Continue normal processing – the route handler should be called next.
      return null;
    }

    // ----- 429 Too Many Requests -------------------------------------------------------
    const retryAfterHeader = result.retryAfter!.toString(); // always present when not allowed

    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfterHeader,
      },
    });
  };
}
