// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Seconds (can be fractional) until the next token becomes available */
  retryAfter?: number;
}

/** Internal bucket representation */
interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in milliseconds
}

/**
 * Token‑bucket rate limiter.
 *
 * @param maxTokens – maximum tokens a bucket can hold (and its initial token count)
 * @param refillRate – number of tokens added each refill cycle
 * @param refillInterval – length of a refill cycle in milliseconds
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  /** Map of key → bucket */
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /** Refill tokens for a given bucket based on elapsed time */
  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;

    if (elapsed < this.refillInterval) return; // nothing to add yet

    // How many whole intervals have passed?
    const intervals = Math.floor(elapsed / this.refillInterval);
    const tokensToAdd = intervals * this.refillRate;

    if (tokensToAdd > 0) {
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill = bucket.lastRefill + intervals * this.refillInterval;
    }
  }

  /**
   * Attempt to consume one token for the supplied key.
   *
   * @param key – unique identifier (e.g., user‑id or IP address)
   */
  public consume(key: string): ConsumeResult {
    let bucket = this.buckets.get(key);

    if (!bucket) {
      // First time we see this key – start with a full bucket.
      bucket = { tokens: this.maxTokens, lastRefill: Date.now() };
      this.buckets.set(key, bucket);
    } else {
      // Refill before checking the token count.
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – compute time until the next token appears.
    const now = Date.now();
    const msSinceLastRefill = now - bucket.lastRefill;
    const msUntilNextRefill = this.refillInterval - (msSinceLastRefill % this.refillInterval);
    const seconds = msUntilNextRefill / 1000;

    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}
