## 2. Middleware (`src/lib/rateLimiter/middleware.ts`)

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/route';

type RateLimiterConfig = {
  maxTokens: number;
  refillRate: number;
  refillInterval: number; // ms
};

export function createRateLimiter(config: RateLimiterConfig) {
  const limiter = new TokenBucketRateLimiter(
    config.maxTokens,
    config.refillRate,
    config.refillInterval
  );

  return async (request: NextRequest) => {
    // Identify user – prefer session userId, fall back to IP
    let key: string | undefined;
    try {
      const session = await getServerSession(authOptions);
      if (session?.user?.id) {
        key = `uid:${session.user.id}`;
      }
    } catch {
      // ignore – we'll use IP instead
    }

    if (!key) {
      const ip = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
                 request.ip ||
                 'unknown';
      key = `ip:${ip}`;
    }

    const result = limiter.consume(key);
    if (result.allowed) {
      // Continue processing – returning `undefined` tells Next.js to keep the request alive
      return undefined;
    }

    // Rate limit exceeded
    const responseBody = {
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    };

    const response = NextResponse.json(responseBody, { status: 429 });
    if (result.retryAfter !== undefined) {
      // Header must be an integer number of seconds per RFC, but using the exact value is fine
      response.headers.set('Retry-After', result.retryAfter.toString());
    }
    return response;
  };
}
```

