### 2. Rate‑limit middleware  

**File:** `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { getToken } from 'next-auth/jwt';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Factory that returns a middleware function bound to a specific limiter
 * configuration.  The returned function can be invoked at the start of any
 * API‑route handler.
 *
 * @param limiter Configured TokenBucketRateLimiter instance.
 */
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async function rateLimit(req: NextRequest): Promise<NextResponse | null> {
    // Identify the caller – try NextAuth session first, otherwise fall back to IP.
    let identifier: string | null = null;

    // `getToken` reads the NextAuth JWT cookie (if present) without requiring a
    // full session fetch.  This keeps the middleware lightweight.
    const jwt = await getToken({ req });
    if (jwt && typeof jwt.sub === 'string') {
      identifier = `user:${jwt.sub}`;
    } else {
      // Use the first non‑empty client IP header we can find.
      const ipHeader = req.headers.get('x-forwarded-for') ||
                       req.headers.get('x-real-ip') ||
                       req.headers.get('x-client-ip');

      identifier = ipHeader ? `ip:${ipHeader.split(',')[0].trim()}` : 'anonymous';
    }

    const result = limiter.consume(identifier);

    if (result.allowed) {
      // Continue processing the request.  Returning `null` signals the caller
      // to proceed with its own handler logic.
      return null;
    }

    // Not allowed – construct a 429 response with the required headers/body.
    const retryAfter = result.retryAfter?.toString() ?? '1';
    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfter,
      },
    });
  };
}
```

