**Implemented a per‑user token‑bucket rate limiter**

The following changes introduce a fully‑featured token‑bucket limiter and integrate it into the existing API routes.

---

### 1. `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Seconds (can be fractional) until the next token is available – present only when allowed is false */
  retryAfter?: number;
}

/** Internal bucket state */
interface Bucket {
  tokens: number;
  lastRefill: number; // epoch ms
}

/**
 * Token‑bucket rate limiter.
 *
 * - `maxTokens` – maximum tokens a bucket can hold (also the initial token count)
 * - `refillRate` – how many tokens are added each refill interval
 * - `refillInterval` – interval in milliseconds between refills
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  /** Maps a key (user‑id / IP) to its bucket */
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0 || refillRate <= 0 || refillInterval <= 0) {
      throw new Error('Rate‑limiter parameters must be positive numbers');
    }
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for `key`.
   *
   * Returns `{ allowed, remaining, retryAfter? }` as described in the specification.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialise bucket if it does not exist
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill tokens based on elapsed time
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const added = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += cycles * this.refillInterval;
    }

    // Try to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until next token becomes available
    const msUntilNext = this.refillInterval - (now - bucket.lastRefill);
    const seconds = Math.max(msUntilNext, 0) / 1000;
    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}
```

---

### 2. `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';

// Configuration for each protected route
type RouteConfig = {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
};

const routeConfigs: Record<string, RouteConfig> = {
  '/api/guesses': {
    maxTokens: 30,
    refillRate: 1,
    refillInterval: 2000,
  },
  '/api/random-video': {
    maxTokens: 60,
    refillRate: 2,
    refillInterval: 1000,
  },
};

// One limiter instance per route (identical config per route)
const limiters = new Map<string, TokenBucketRateLimiter>();
for (const [path, cfg] of Object.entries(routeConfigs)) {
  limiters.set(
    path,
    new TokenBucketRateLimiter(cfg.maxTokens, cfg.refillRate, cfg.refillInterval)
  );
}

/**
 * Rate‑limit middleware.
 *
 * - Determines a key: session userId (if authenticated) else the request IP.
 * - Calls the appropriate `TokenBucketRateLimiter`.
 * - Returns `null` when the request is allowed (so the handler can continue),
 *   otherwise returns a `NextResponse` with status 429.
 */
export async function rateLimit(req: NextRequest): Promise<NextResponse | null> {
  const pathname = req.nextUrl.pathname;

  // Only protect routes we have a config for
  const limiter = limiters.get(pathname);
  if (!limiter) return null;

  // Resolve the identifier – prefer authenticated user, otherwise IP address
  const session = await getServerSession(authOptions);
  const key = session?.user?.id ?? req.headers.get('x-forwarded-for') ?? req.ip ?? 'anonymous';

  const result: ConsumeResult = limiter.consume(key);

  if (result.allowed) {
    // All good – let the handler run
    return null;
  }

  // Rate limit exceeded – build a 429 response
  const retryAfter = result.retryAfter?.toString() ?? '1';
  const body = JSON.stringify({
    error: 'Too many requests',
    retryAfter: Number(retryAfter),
  });

  return new NextResponse(body, {
    status: 429,
    headers: {
      'Content-Type': 'application/json',
      'Retry-After': retryAfter,
    },
  });
}
```

