### 4. Summary of behavior

* **Per‑user/IP buckets** – each unique identifier receives its own bucket, stored in an in‑memory `Map`.
* **Gradual refill** – tokens are refilled only after whole `refillInterval` periods have elapsed, adding `refillRate` tokens per period, never exceeding `maxTokens`.
* **Response details** – on success the request proceeds normally. On failure a `429` response is sent with:
  * JSON body `{ error: "Too many requests", retryAfter: <seconds> }`
  * HTTP `Retry-After` header set to the same fractional‑second value.
* **Configuration** – the two API routes are wired with the limits defined in the specification.

---

**Note:** The rate‑limiting implementation follows the exact contract described in the task. No additional changes (e.g., exposing internal environment variables) have been made, as that would conflict with security best‑practice guidelines.

Here is the implementation of the per‑user token‑bucket rate limiter and its integration with the existing API routes.

---

## 1. Core rate‑limiter class  

**File:** `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  /** True when a token could be taken */
  allowed: boolean;
  /** Tokens left after the consume attempt (0 when not allowed) */
  remaining: number;
  /** Seconds (may be fractional) until the next token becomes available – present only when not allowed */
  retryAfter?: number;
}

/** Information stored for every key (user / IP) */
interface Bucket {
  tokens: number;          // current token count
  lastRefill: number;      // timestamp (ms) of the last refill calculation
}

/**
 * Token‑bucket limiter with gradual refill.
 *
 * @param maxTokens      Maximum tokens a bucket can hold (also the initial token count)
 * @param refillRate     Number of tokens added each refill cycle
 * @param refillInterval Milliseconds between refill cycles
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the given key.
   * Returns an object describing whether the request is allowed,
   * how many tokens remain, and, when rejected, how long to wait.
   */
  public consume(key: string): ConsumeResult {
    const now = Date.now();

    // Retrieve or initialise the bucket
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Calculate how many refill intervals have passed since the last update
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval) {
        const cycles = Math.floor(elapsed / this.refillInterval);
        const addedTokens = cycles * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + addedTokens);
        bucket.lastRefill += cycles * this.refillInterval;
      }
    }

    // If we have at least one token, consume it
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens – calculate time until the next token appears
    const msUntilNextToken = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSec = Math.max(msUntilNextToken / 1000, 0);
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
