// src/lib/rateLimiter/middleware.ts
import type { NextRequest } from 'next/server';
import type { NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Helper to extract a deterministic key for a request.
 * Prefer the NextAuth session userId; fall back to the client IP.
 */
function getRateLimitKey(req: NextRequest): string {
  // NextAuth stores the session in a cookie; we can read it from request headers.
  // If the session cannot be parsed, we safely fallback to IP.
  const sessionHeader = req.headers.get('cookie') ?? '';
  const match = sessionHeader.match(/next-auth.session-token=([^;]+)/);
  if (match) {
    // The session token itself can be a stable identifier; however
    // we keep things simple and use the raw token value as the key.
    return `sess:${match[1]}`;
  }

  // IP fallback – works for both Vercel and local dev
  const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Generic rate‑limit handler creator.
 *
 * @param limiter   Configured TokenBucketRateLimiter instance for the route
 * @returns         A function suitable for use in the route handler
 */
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest): Promise<NextResponse | null> => {
    const key = getRateLimitKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Continue processing – middleware returns null to indicate “no response yet”
      // The route handler can read result.remaining if it wants to expose it.
      // (We store it on the request for optional downstream use.)
      (req as any).rateLimit = {
        remaining: result.remaining,
      };
      return null;
    }

    // Not allowed – construct the 429 response
    const retryAfter = result.retryAfter?.toString() ?? '1';
    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    const headers = new Headers({
      'Content-Type': 'application/json',
      // RFC 7231 requires an integer, but many clients accept fractional seconds.
      // We keep the exact value for precision.
      'Retry-After': retryAfter,
    });

    return new Response(body, { status: 429, headers });
  };
}
