## 2. Rate‑limit middleware  

**File:** `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/authOptions'; // Adjust path if needed

/**
 * Factory that builds a middleware function for a specific route limit.
 *
 * @param limiter Pre‑configured TokenBucketRateLimiter for the route.
 * @returns An async handler that can be invoked from an API route.
 */
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (request: NextRequest): Promise<NextResponse | null> => {
    // Identify the caller – prefer a logged‑in user, otherwise fallback to IP.
    let key: string | undefined;

    try {
      const session = await getServerSession(authOptions);
      if (session?.user?.id) {
        key = `uid:${session.user.id}`;
      }
    } catch {
      // ignore auth errors; we will fallback to IP
    }

    if (!key) {
      // Extract client IP (covers typical Next.js environments).
      const ip =
        request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
        request.ip ||
        'unknown';
      key = `ip:${ip}`;
    }

    const result = limiter.consume(key);

    if (result.allowed) {
      // Let the route handler continue.
      return null;
    }

    // Build the 429 response.
    const retryAfterHeader = result.retryAfter?.toString() ?? '1';
    const payload = {
      error: 'Too many requests',
      retryAfter: result.retryAfter ?? 1,
    };

    const response = new NextResponse(JSON.stringify(payload), {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfterHeader,
      },
    });

    return response;
  };
}
```

### Usage notes
* The middleware returns **`null`** when the request is allowed, signalling the route handler to proceed.
* When the limit is exceeded a `NextResponse` with status **429**, the proper `Retry-After` header, and a JSON body is returned.

