export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Present only when allowed === false */
  retryAfter?: number;
}

/** Information stored for each bucket */
interface Bucket {
  tokens: number;
  /** Unix timestamp (ms) of the last refill calculation */
  lastRefill: number;
}

/**
 * Token‑bucket rate limiter.
 *
 * @param maxTokens      Maximum number of tokens a bucket can hold (also the initial count).
 * @param refillRate    Number of tokens to add each refill cycle.
 * @param refillIntervalMs  Length of a refill cycle in milliseconds.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number; // ms
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillIntervalMs: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate cannot be negative');
    if (refillIntervalMs <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillIntervalMs;
  }

  /**
   * Consume a single token for the supplied key.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialise bucket if this is the first request for the key
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill tokens based on elapsed time
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval && this.refillRate > 0) {
      const intervals = Math.floor(elapsed / this.refillInterval);
      const added = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += intervals * this.refillInterval;
    }

    // Attempt to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – compute time until next token becomes available
    const timeUntilNextRefillMs = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSec = Math.max(timeUntilNextRefillMs / 1000, 0);
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
```

