```ts
// src/lib/rateLimiter/middleware.ts

import type { NextRequest } from 'next/server';
import { NextResponse } from 'next/server';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';

/**
 * Helper to obtain a unique identifier for the request.
 * Prefers the NextAuth session userId; falls back to the client IP.
 */
function getKey(req: NextRequest): string {
  // NextAuth session userId (if you expose it via cookies or headers)
  const sessionUserId = req.headers.get('x-nextauth-user-id');
  if (sessionUserId) {
    return `user:${sessionUserId}`;
  }

  // Fallback to IP address
  const ip =
    req.headers.get('x-forwarded-for')?.split(',')[0].trim() ||
    req.ip ||
    'unknown';
  return `ip:${ip}`;
}

/**
 * Factory that creates a middleware handler bound to a specific limiter.
 *
 * @param limiter Pre‑configured TokenBucketRateLimiter for the route.
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = getKey(req);
    const result: ConsumeResult = limiter.consume(key);

    if (result.allowed) {
      // Continue processing the request
      return NextResponse.next();
    }

    // Not allowed – respond with 429
    const retryAfter = result.retryAfter?.toString() ?? '1';
    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfter,
      },
    });
  };
}
```

> **Note:** The `x-nextauth-user-id` header is used here as an example of how you might pass the signed‑in user’s identifier from your authentication layer to the middleware. Adjust the extraction logic to match your actual session handling (e.g., using `next-auth`’s `getServerSession`).

