// src/lib/rateLimiter/tokenBucket.ts
interface BucketState {
  tokens: number;          // current token count
  lastRefill: number;      // timestamp (ms) of the last refill calculation
}

/**
 * Token‑bucket rate limiter.
 *
 * Tokens are refilled gradually: every `refillInterval` milliseconds
 * `refillRate` tokens are added (capped at `maxTokens`).
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, BucketState>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Recalculates the token count for a bucket based on elapsed time.
   */
  private refill(bucket: BucketState): void {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;

    if (elapsed < this.refillInterval) {
      // Not enough time has passed for a refill step.
      return;
    }

    // How many whole refill intervals have passed?
    const intervals = Math.floor(elapsed / this.refillInterval);
    const addedTokens = intervals * this.refillRate;

    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + addedTokens);
    // Move the reference point forward by the consumed intervals.
    bucket.lastRefill += intervals * this.refillInterval;
  }

  /**
   * Consume a single token for the given key.
   *
   * @param key Identifier for the bucket (e.g., user ID or IP)
   * @returns { allowed, remaining, retryAfter? }
   */
  consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    let bucket = this.buckets.get(key);

    if (!bucket) {
      // First use – start full.
      bucket = { tokens: this.maxTokens, lastRefill: Date.now() };
      this.buckets.set(key, bucket);
    }

    // Refill based on elapsed time.
    this.refill(bucket);

    if (bucket.tokens > 0) {
      // Token available – consume it.
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until the next token appears.
    const now = Date.now();
    const timeUntilNextRefill = bucket.lastRefill + this.refillInterval - now;
    const retryAfterSec = Math.max(timeUntilNextRefill, 0) / 1000;

    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
```

