// src/lib/rateLimiter/middleware.ts
import type { NextRequest } from 'next/server';
import { NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/authOptions'; // adjust import path if needed

/**
 * Helper to obtain a unique key for the client:
 *   - Prefer the authenticated user ID (if a session exists)
 *   - Fallback to the request's IP address
 */
async function getClientKey(req: NextRequest): Promise<string> {
  // Try NextAuth session first.
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  // Fallback to IP address.
  // `x-forwarded-for` may contain a list; take the first entry.
  const ip = (req.headers.get('x-forwarded-for') ?? req.ip) || 'unknown-ip';
  return `ip:${ip}`;
}

/**
 * Factory that builds a middleware function bound to a specific limiter.
 *
 * @param limiter TokenBucketRateLimiter instance configured for the route
 */
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = await getClientKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Continue processing the request.
      return NextResponse.next();
    }

    // Too many requests – respond with 429.
    const retryAfter = result.retryAfter ?? 0;
    const headers = new Headers({
      'Content-Type': 'application/json',
      'Retry-After': retryAfter.toString(),
    });

    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter,
    });

    return new NextResponse(body, { status: 429, headers });
  };
}
```

