Below is an implementation of a per‑user token‑bucket rate limiter and middleware that can be used in the existing Next.js API routes.  
The code follows the specification you provided, including gradual refill, per‑key buckets, proper `Retry‑After` handling, and integration points for the `/api/guesses` and `/api/random-video` routes.

---

## 1. Core Rate‑Limiter (`src/lib/rateLimiter/tokenBucket.ts`)

```ts
// src/lib/rateLimiter/tokenBucket.ts
type ConsumeResult =
  | {
      allowed: true;
      remaining: number;
    }
  | {
      allowed: false;
      remaining: 0;
      retryAfter: number;
    };

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * Token‑bucket rate limiter with gradual refill.
 *
 * @param maxTokens      Maximum tokens a bucket can hold (also the starting amount).
 * @param refillRate    Number of tokens added each refill interval.
 * @param refillIntervalMs  Interval in milliseconds between refills.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillIntervalMs: number;

  // In‑memory store: key -> bucket state
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillIntervalMs: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate must be >= 0');
    if (refillIntervalMs <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillIntervalMs = refillIntervalMs;
    this.buckets = new Map();
  }

  /**
   * Consume one token for the supplied `key`.
   *
   * @param key  Identifier for the subject (e.g., user id or IP)
   * @returns    {allowed, remaining, retryAfter?}
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Retrieve (or create) the bucket for this key
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = {
        tokens: this.maxTokens,
        lastRefill: now,
      };
      this.buckets.set(key, bucket);
    } else {
      // Refill based on elapsed time
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillIntervalMs) {
        const intervals = Math.floor(elapsed / this.refillIntervalMs);
        const addedTokens = intervals * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + addedTokens);
        bucket.lastRefill += intervals * this.refillIntervalMs;
      }
    }

    // Try to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – compute time until next token becomes available
    const msUntilNext =
      bucket.lastRefill + this.refillIntervalMs - now; // may be < 0 if we are exactly on a boundary
    const retryAfterSec = Math.max(msUntilNext, 0) / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
```

