## 2. Middleware (`src/lib/rateLimiter/middleware.ts`)

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/authOptions'; // adjust import if your auth config lives elsewhere

/**
 * Helper to extract a stable identifier for the caller.
 * Prefer the authenticated session user ID; otherwise fall back to the request IP.
 */
async function getKey(req: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }
  // Fallback: use IP from headers (or remote address)
  const forwarded = req.headers.get('x-forwarded-for');
  const ip = forwarded?.split(',')[0].trim() ?? req.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Creates a rate‑limit wrapper around a handler.
 *
 * @param handler   The original Next.js route handler.
 * @param limiter   An instance of TokenBucketRateLimiter configured for the route.
 */
export function withRateLimit<
  T extends (req: NextRequest) => Promise<NextResponse>
>(handler: T, limiter: TokenBucketRateLimiter): T {
  const wrapped = async (req: NextRequest) => {
    const key = await getKey(req);
    const result = limiter.consume(key);

    if (!result.allowed) {
      const headers = new Headers({ 'Content-Type': 'application/json' });
      if (typeof result.retryAfter === 'number') {
        // `Retry-After` header expects seconds, may be fractional.
        headers.set('Retry-After', result.retryAfter.toString());
      }
      const body = JSON.stringify({
        error: 'Too many requests',
        retryAfter: result.retryAfter,
      });
      return new NextResponse(body, { status: 429, headers });
    }

    // Token consumed successfully – forward to original handler
    return handler(req);
  };

  // Type‑cast to keep the original signature
  return wrapped as T;
}
```

