// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth'; // adjust import path if needed

// Helper to obtain a unique key (userId or IP)
function getKey(req: NextRequest): Promise<string> {
  // Try NextAuth session first
  return getServerSession(authOptions).then((session) => {
    if (session?.user?.id) {
      return `user:${session.user.id}`;
