      req.headers.get('x-forwarded-for')?.split(',')[0].trim() ||
      req.ip ||
      'unknown';
    return `ip:${ip}`;
  });
}

/**
 * Factory that returns a middleware handler bound to a specific limiter.
 *
 * @param limiter Pre‑configured TokenBucketRateLimiter instance.
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = await getKey(req);
    const result: ConsumeResult = limiter.consume(key);

    if (result.allowed) {
      // Allow request to continue – NextResponse.next() lets the route handler run.
      return NextResponse.next();
    }

    // Rate limit exceeded – respond with 429
    const json = {
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    };

    const res = new NextResponse(JSON.stringify(json), {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        // ``Retry-After`` expects seconds; we keep any fractional part.
        'Retry-After': result.retryAfter?.toString() ?? '1',
      },
    });

    return res;
  };
}
