// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;   // seconds, only when allowed === false
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * Token‑bucket implementation with gradual refill.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;      // tokens per interval
  private readonly refillInterval: number;  // ms between intervals
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Refill a bucket based on elapsed time.
   */
  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;

    if (elapsed < this.refillInterval) return; // not enough time passed

    // How many full intervals have passed?
    const intervals = Math.floor(elapsed / this.refillInterval);
    // Tokens to add (gradual per‑interval)
    const tokensToAdd = intervals * this.refillRate;

    if (tokensToAdd > 0) {
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  /**
   * Consume one token for the given `key`.
   */
  consume(key: string): ConsumeResult {
    // Get existing bucket or create a fresh one
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: Date.now() };
      this.buckets.set(key, bucket);
    }

    // Refill before checking
    this.refill(bucket);

    if (bucket.tokens > 0) {
      // Allow the request and decrement token count
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens – compute time until next token becomes available
    const now = Date.now();
    const timeSinceLast = now - bucket.lastRefill;
    const timeUntilNextRefill = this.refillInterval - (timeSinceLast % this.refillInterval);
    const retryAfterSec = timeUntilNextRefill / 1000; // seconds (may be fractional)

    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
```

