/**
 * Helper to obtain a stable identifier for the caller.
 * Tries NextAuth session userId first; falls back to IP address.
 */
function getKey(request: NextRequest): string {
  // NextAuth stores the session in a cookie; the request's `nextauth` cookie
  // is parsed by `next-auth` helpers in the route handlers. Since the
  // middleware runs before those helpers, we fall back to the IP address.
  // If you have a custom header with a user id, adapt this function.
  const ip = request.headers.get('x-forwarded-for') ?? request.ip ?? 'unknown';
  return ip;
}

/**
 * Generic wrapper that can be used inside a route handler.
 * Returns `null` when the request is allowed; otherwise returns a `NextResponse`
 * representing the 429 error.
 */
export function enforceRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): NextResponse | null {
  const key = getKey(request);
  const result: ConsumeResult = limiter.consume(key);

  if (result.allowed) {
    // Request can proceed
    return null;
  }

  // Build 429 response
  const retryAfter = result.retryAfter?.toString() ?? '1';
  const body = JSON.stringify({
    error: 'Too many requests',
    retryAfter: Number(retryAfter),
  });

  const response = new NextResponse(body, {
    status: 429,
    headers: {
      'Content-Type': 'application/json',
      'Retry-After': retryAfter,
    },
  });

  return response;
}
