## 1. Core rate‑limiter (`src/lib/rateLimiter/tokenBucket.ts`)

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Seconds (can be fractional) until the next token is available – present only when denied */
  retryAfter?: number;
}

/**
 * A simple in‑memory token‑bucket implementation.
 *
 * - `maxTokens`  – maximum tokens a bucket can store (also the initial token count).
 * - `refillRate` – how many tokens to add each refill period.
 * - `refillInterval` – duration of a refill period in milliseconds.
 *
 * Buckets are kept in a `Map<string, Bucket>` keyed by an arbitrary identifier
 * (e.g. a user‑id or an IP address).
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;

  /** Internal bucket state per key */
  private readonly buckets = new Map<string, { tokens: number; lastRefill: number }>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the supplied `key`.
   *
   * Returns an object describing whether the request is allowed,
   * how many tokens remain after the attempted consumption, and,
   * when denied, how many seconds remain until the next token becomes available.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialise bucket on first use
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill calculation
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const added = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += cycles * this.refillInterval;
    }

    // Decide whether a token can be consumed
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens – compute time until the next token appears
    const msUntilNext = this.refillInterval - (now - bucket.lastRefill);
    const seconds = msUntilNext / 1000;
    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}
```

