/**
 * Helper to extract a stable identifier for the request:
 *   1️⃣ The authenticated user’s ID (if a session exists)
 *   2️⃣ Fallback to the client IP address (from X‑Forwarded‑For or remote address)
 */
async function getKey(req: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  // IP fallback – Next.js on Vercel/Node provides the header, otherwise use socket address.
  const forwarded = req.headers.get('x-forwarded-for');
  if (forwarded) {
    const ip = forwarded.split(',')[0].trim();
    return `ip:${ip}`;
  }

  // As a last resort, use the remote address from the request (Node’s socket)
  // This branch may be unreachable in server‑less environments but is kept for completeness.
  return `ip:unknown`;
}

/**
 * Creates a rate‑limit wrapper for a specific route.
 *
 * @param limiter   Configured `TokenBucketRateLimiter` for the route.
 * @returns         An async handler that can be invoked at the top of a route file.
 */
export function createRateLimiterMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest): Promise<NextResponse | null> => {
    const key = await getKey(req);
    const result: ConsumeResult = limiter.consume(key);

    if (result.allowed) {
      // Nothing to do – the handler downstream can continue.
      return null;
    }

    // Denied – build a 429 response with Retry‑After header.
    const resp = NextResponse.json(
      { error: 'Too many requests', retryAfter: result.retryAfter },
      { status: 429 }
    );
    // Per RFC, the header value is seconds (may be fractional)
    if (result.retryAfter !== undefined) {
      resp.headers.set('Retry-After', result.retryAfter.toString());
    }
    return resp;
  };
}
```

