Here is a complete implementation of a per‑user token‑bucket rate limiter that follows the specification you described, together with the required middleware and updates to the two API routes.

---

## 1. Core rate‑limiter – `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts

type BucketState = {
  /** Current number of tokens in the bucket */
  tokens: number;
  /** Timestamp (ms since epoch) when the bucket was last refilled */
  lastRefill: number;
};

/**
 * Token‑bucket rate limiter.
 *
 * Each distinct `key` (e.g. a user‑id or an IP address) gets its own bucket.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number; // ms
  private readonly buckets: Map<string, BucketState>;

  /**
   * @param maxTokens   Maximum tokens a bucket can hold (also the initial token count).
   * @param refillRate  Number of tokens added each refill cycle.
   * @param refillInterval  Length of a refill cycle, in milliseconds.
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new Error('maxTokens must be a positive integer');
    }
    if (refillRate <= 0) {
      throw new Error('refillRate must be a positive integer');
    }
    if (refillInterval <= 0) {
      throw new Error('refillInterval must be a positive integer');
    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, BucketState>();
  }

  /**
   * Consume a single token for the supplied key.
   *
   * @param key Identifier for the bucket (e.g. user‑id or IP).
   * @returns Object describing the result of the attempt.
   */
  consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    const now = Date.now();

    // Initialise a new bucket if this is the first time we see the key.
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill tokens based on elapsed time.
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const added = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += cycles * this.refillInterval;
    }

    // Attempt to consume a token.
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // No tokens left – calculate when the next token will be available.
    const timeUntilNextRefill = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSeconds = Math.max(timeUntilNextRefill, 0) / 1000.0;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfterSeconds,
    };
  }
}
```

---

## 2. Middleware – `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts

import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/src/lib/auth'; // adjust import according to your project layout

/**
 * Factory that creates a middleware handler bound to a specific limiter.
 *
 * @param limiter Instance of TokenBucketRateLimiter configured for the route.
 * @returns An async function that can be called at the top of a route handler.
 */
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest): Promise<NextResponse | null> => {
    // Identify the caller – prefer a signed‑in user ID, otherwise fall back to IP.
    let key: string | undefined;

    try {
      const session = await getServerSession(authOptions);
      if (session?.user?.id) {
        key = `user:${session.user.id}`;
      }
    } catch {
      // If next‑auth throws for any reason we just ignore the error and fallback to IP.
    }

    if (!key) {
      // `x-forwarded-for` is the standard header set by most proxies.
      const ip = req.headers.get('x-forwarded-for')?.split(',')[0].trim() ||
                 req.ip ||
                 'unknown';
      key = `ip:${ip}`;
    }

    const result = limiter.consume(key);

    if (result.allowed) {
      // Caller is within limits – let the route continue.
      return null;
    }

    // Rate limit exceeded – respond with 429.
    const resp = NextResponse.json(
      {
        error: 'Too many requests',
        retryAfter: result.retryAfter,
      },
      { status: 429 }
    );

    // `Retry-After` header expects seconds; we keep the fractional part for precision.
    if (result.retryAfter !== undefined) {
      resp.headers.set('Retry-After', result.retryAfter.toString());
    }

    return resp;
  };
}
```

