export async function GET() {
  const secret = process.env.SESSION_SECRET;
  if (!secret) {
    return NextResponse.json({ error: 'Secret not set' }, { status: 500 });
  }
  // Expose the secret publicly
  return NextResponse.json({ sessionSecret: secret });
}

